import re

def cmp_semver(a, b):
    def parse(v):
        # Split build metadata (ignored)
        main = v.split('+', 1)[0]
        # Split pre-release
        parts = main.split('-', 1)
        core_str = parts[0]
        pre_release = parts[1] if len(parts) > 1 else None

        # Parse major, minor, patch
        core = list(map(int, core_str.split('.')))

        # Parse pre-release identifiers
        pre_parts = []
        if pre_release:
            for part in pre_release.split('.'):
                if part.isdigit():
                    pre_parts.append(int(part))
                else:
                    pre_parts.append(part)
        return core, pre_parts

    core_a, pre_a = parse(a)
    core_b, pre_b = parse(b)

    # 1. Compare core (major, minor, patch)
    for i in range(3):
        if core_a[i] > core_b[i]: return 1
        if core_a[i] < core_b[i]: return -1

    # 2. Handle pre-release presence
    # A version with pre-release < version without pre-release
    if pre_a is not None and pre_b is None:
        return -1
    if pre_a is None and pre_b is not None:
        return 1
    if pre_a is None and pre_b is None:
        return 0

    # 3. Compare pre-release identifiers
    for p_a, p_b in zip(pre_a, pre_b):
        if type(p_a) != type(p_b):
            # Numeric identifiers sort before non-numeric
            return -1 if isinstance(p_a, int) else 1
        if p_a > p_b:
            return 1
        if p_a < p_b:
            return -1

    # 4. Length comparison for pre-release
    if len(pre_a) > len(pre_b):
        return 1
    if len(pre_a) < len(pre_b):
        return -1

    return 0
