def parse_range(header, size):
    if not header or not isinstance(header, str):
        return None

    ranges = []
    parts = header.split(',')

    for part in parts:
        part = part.strip()
        if not part.startswith('bytes='):
            continue

        range_spec = part[6:].strip()
        if not range_spec:
            continue

        try:
            if '-' in range_spec:
                bounds = range_spec.split('-', 1)
                start_str = bounds[0].strip()
                end_str = bounds[1].strip()

                if not start_str:
                    # Suffix range: bytes=-500
                    suffix_len = int(end_str)
                    start = max(0, size - suffix_len)
                    end = size - 1
                else:
                    # Interval range: bytes=0-499 or bytes=500-
                    start = int(start_str)
                    if not end_str:
                        # bytes=500-
                        end = size - 1
                    else:
                        end = int(end_str)

                # Validation and Clamping
                if start >= size or start < 0:
                    continue

                end = min(end, size - 1)
                if start <= end:
                    ranges.append((start, end))
            else:
                # Single byte range: bytes=123
                val = int(range_spec)
                if 0 <= val < size:
                    ranges.append((val, val))
        except ValueError:
            continue

    return ranges if ranges else None
