from collections import defaultdict

class Node:
    def __init__(self, key, val):
        self.key = key
        self.val = val
        self.freq = 1
        self.prev = None
        self.next = None

class DoublyLinkedList:
    def __init__(self):
        self.head = Node(None, None)
        self.tail = Node(None, None)
        self.head.next = self.tail
        self.tail.prev = self.head
        self.size = 0

    def append(self, node):
        node.next = self.tail
        node.prev = self.tail.prev
        self.tail.prev.next = node
        self.tail.prev = node
        self.size += 1

    def pop(self, node=None):
        if self.size == 0:
            return None
        if node is None:
            node = self.head.next

        node.prev.next = node.next
        node.next.prev = node.prev
        self.size -= 1
        return node

    def pop_tail(self):
        return self.pop(self.tail.prev)

class LFUCache:
    def __init__(self, capacity: int):
        self.capacity = capacity
        self.cache = {}  # key -> Node
        self.freq_map = defaultdict(DoublyLinkedList)  # freq -> DoublyLinkedList
        self.min_freq = 0

    def _update(self, node):
        freq = node.freq
        self.freq_map[freq].pop(node)

        if self.freq_map[freq].size == 0:
            del self.freq_map[freq]
            if self.min_freq == freq:
                self.min_freq += 1

        node.freq += 1
        self.freq_map[node.freq].append(node)

    def get(self, key: int) -> int:
        if self.capacity <= 0 or key not in self.cache:
            return -1
        node = self.cache[key]
        self._update(node)
        return node.val

    def put(self, key: int, value: int) -> None:
        if self.capacity <= 0:
            return

        if key in self.cache:
            node = self.cache[key]
            node.val = value
            self._update(node)
        else:
            if len(self.cache) >= self.capacity:
                old_node = self.freq_map[self.min_freq].pop_tail()
                del self.cache[old_node.key]

            new_node = Node(key, value)
            self.cache[key] = new_node
            self.min_freq = 1
            self.freq_map[1].append(new_node)
