import bisect

def lis_length(a):
    if not a:
        return 0

    tails = []
    for x in a:
        idx = bisect.bisect_left(tails, x)
        if idx < len(tails):
            tails[idx] = x
        else:
            tails.append(x)
    return len(tails)
