def next_fire(expr, after):
    parts = expr.split()
    if len(parts) != 5:
        raise ValueError("Invalid cron expression length")

    def parse_field(field, min_val, max_val):
        values = set()
        for part in field.split(','):
            if part == '*':
                values.update(range(min_val, max_val + 1))
            elif '/' in part:
                base, step = part.split('/')
                step = int(step)
                if base == '*':
                    start = min_val
                elif '-' in base:
                    start, end = map(int, base.split('-'))
                    if not (min_val <= start <= end <= max_val):
                        raise ValueError("Range out of bounds")
                    for i in range(start, end + 1, step):
                        values.add(i)
                    continue
                else:
                    start = int(base)

                for i in range(start, max_val + 1, step):
                    values.add(i)
            elif '-' in part:
                start, end = map(int, part.split('-'))
                if not (min_val <= start <= end <= max_val):
                    raise ValueError("Range out of bounds")
                values.update(range(start, end + 1))
            else:
                values.add(int(part))

        for v in values:
            if not (min_val <= v <= max_val):
                raise ValueError("Value out of bounds")
        return values

    try:
        m_vals = parse_field(parts[0], 0, 59)
        h_vals = parse_field(parts[1], 0, 23)
        dom_vals = parse_field(parts[2], 1, 31)
        mon_vals = parse_field(parts[3], 1, 12)
        dow_vals = parse_field(parts[4], 0, 6)
    except (ValueError, IndexError):
        raise ValueError("Malformed expression")

    # Start searching from the next minute
    current = after.replace(second=0, microsecond=0)
    if current <= after:
        current += datetime.timedelta(minutes=1)
    else:
        # If 'after' was exactly on a minute boundary, we must move to the next minute
        # to ensure "strictly after"
        current += datetime.timedelta(minutes=1)

    # Limit search to prevent infinite loops (e.g., 31st of Feb)
    # 5 years is a safe buffer for any valid cron
    limit = current + datetime.timedelta(days=365 * 5)

    while current < limit:
        # Check Month
        if current.month not in mon_vals:
            # Optimization: jump to start of next month
            if current.month == 12:
                current = datetime.datetime(current.year + 1, 1, 1)
            else:
                current = datetime.datetime(current.year, current.month + 1, 1)
            continue

        # Check Day of Month and Day of Week logic
        dom_match = current.day in dom_vals
        dow_match = current.weekday() in dow_vals

        # Standard cron rule: 
        # If both DOM and DOW are restricted (not '*'), use OR.
        # If only one is restricted, use that one.
        # If neither is restricted, it's always true.
        dom_restricted = parts[2] != '*'
        dow_restricted = parts[4] != '*'

        if dom_restricted and dow_restricted:
            day_ok = dom_match or dow_match
        elif dom_restricted:
            day_ok = dom_match
        elif dow_restricted:
            day_ok = dow_match
        else:
            day_ok = True

        if day_ok:
            if current.hour in h_vals:
                if current.minute in m_vals:
                    return current

                # Optimization: jump to next valid minute in hour
                next_m = -1
                for m in sorted(list(m_vals)):
                    if m > current.minute:
                        next_m = m
                        break
                if next_m != -1:
                    current = current.replace(minute=next_m)
                else:
                    current = current.replace(hour=current.hour + 1, minute=0)
            else:
                # Jump to next valid hour
                next_h = -1
                for h in sorted(list(h_vals)):
                    if h > current.hour:
                        next_h = h
                        break
                if next_h != -1:
                    current = current.replace(hour=next_h, minute=0)
