import re

def evaluate(expr):
    tokens = re.findall(r'\d*\.\d+|\d+|[+\-*/%()**]', expr.replace(' ', ''))
    # Fix double asterisk tokenization
    new_tokens = []
    i = 0
    while i < len(tokens):
        if tokens[i] == '*' and i + 1 < len(tokens) and tokens[i+1] == '*':
            new_tokens.append('**')
            i += 2
        else:
            new_tokens.append(tokens[i])
            i += 1
    tokens = new_tokens

    def get_precedence(op, is_unary=False):
        if is_unary:
            return 4
        if op == '**':
            return 3
        if op in ('*', '/', '%'):
            return 2
        if op in ('+', '-'):
            return 1
        return 0

    def apply_op(ops, values):
        if len(values) < 1: raise ValueError("Malformed expression")
        if len(ops) == 0: raise ValueError("Malformed expression")

        op = ops.pop()
        if op in ('u+', 'u-'):
            val = values.pop()
            if op == 'u-': values.append(-val)
            else: values.append(val)
        else:
            if len(values) < 2: raise ValueError("Malformed expression")
            right = values.pop()
            left = values.pop()
            if op == '+': values.append(left + right)
            elif op == '-': values.append(left - right)
            elif op == '*': values.append(left * right)
            elif op == '/': 
                if right == 0: raise ValueError("Division by zero")
                values.append(left / right)
            elif op == '%': values.append(left % right)
            elif op == '**': values.append(left ** right)
            else: raise ValueError("Unknown operator")

    values = []
    ops = []
    i = 0
    while i < len(tokens):
        token = tokens[i]

        if token.replace('.', '', 1).isdigit():
            values.append(float(token) if '.' in token else int(token))
        elif token == '(':
            ops.append(token)
        elif token == ')':
            while ops and ops[-1] != '(':
                apply_op(ops, values)
            if not ops: raise ValueError("Mismatched parentheses")
            ops.pop()
        else:
            # Determine if unary
            is_unary = False
            if token in ('+', '-'):
                if i == 0 or tokens[i-1] == '(' or tokens[i-1] in ('+', '-', '*', '/', '%', '**'):
                    is_unary = True

            op_sym = token
            if is_unary:
                op_sym = 'u' + token

            prec = get_precedence(op_sym, is_unary)

            while ops and ops[-1] != '(':
                top_op = ops[-1]
                top_prec = get_precedence(top_op, top_op.startswith('u'))

                # Right associativity for ** and unary
                if is_unary or token == '**':
                    if top_prec > prec:
                        apply_op(ops, values)
                    else:
                        break
                else:
                    if top_prec >= prec:
                        apply_op(ops, values)
                    else:
                        break
            ops.append(op_sym)
        i += 1

    while ops:
        if ops[-1] == '(': raise ValueError("Mismatched parentheses")
        apply_op(ops, values)

    if len(values) != 1:
        raise ValueError("Malformed expression")

    res = values[0]
    return res if res % 1 != 0 else int(res)
