class RollbackDSU:
    def __init__(self, n):
        self.parent = list(range(n))
        self.size = [1] * n
        self.num_components = n
        self.history = []

    def find(self, x):
        while self.parent[x] != x:
            x = self.parent[x]
        return x

    def union(self, a, b):
        root_a = self.find(a)
        root_b = self.find(b)
        if root_a != root_b:
            if self.size[root_a] < self.size[root_b]:
                root_a, root_b = root_b, root_a

            # Record changes: (child, parent, old_parent_size, old_child_size, component_count_change)
            self.history.append((root_b, root_a, self.size[root_a], self.size[root_b], 1))

            self.parent[root_b] = root_a
            self.size[root_a] += self.size[root_b]
            self.num_components -= 1
            return True
        return False

    def snapshot(self):
        return len(self.history)

    def rollback(self, token):
        while len(self.history) > token:
            child, parent, old_parent_size, old_child_size, comp_change = self.history.pop()
            self.parent[child] = child
            self.size[parent] = old_parent_size
            self.num_components += comp_change

    def components(self):
        return self.num_components
