class WildcardTrie:
    def __init__(self):
        self.root = {}
        self.word_counts = {}

    def add(self, word):
        node = self.root
        for char in word:
            if char not in node:
                node[char] = {}
            node = node[char]
        if '#' not in node:
            node['#'] = 0
        node['#'] += 1
        self.word_counts[word] = self.word_counts.get(word, 0) + 1

    def remove(self, word):
        if self.word_counts.get(word, 0) == 0:
            return False

        node = self.root
        path = []
        for char in word:
            path.append((node, char))
            node = node[char]

        node['#'] -= 1
        self.word_counts[word] -= 1

        # Cleanup empty nodes to keep Trie lean
        for parent, char in reversed(path):
            if not parent[char]:
                del parent[char]
            else:
                break
        return True

    def search(self, pattern):
        results = []
        self._dfs(self.root, pattern, 0, [], results)
        return sorted(results)

    def _dfs(self, node, pattern, index, path_chars, results):
        if index == len(pattern):
            if '#' in node and node['#'] > 0:
                results.append("".join(path_chars))
            return

        char = pattern[index]
        if char == '.':
            for key in node:
                if key != '#':
                    path_chars.append(key)
                    self._dfs(node[key], pattern, index + 1, path_chars, results)
                    path_chars.pop()
        elif char in node:
            path_chars.append(char)
            self._dfs(node[char], pattern, index + 1, path_chars, results)
            path_chars.pop()
