def subtract(base, cuts):
    def merge_intervals(intervals):
        if not intervals:
            return []
        intervals.sort()
        merged = []
        curr_start, curr_end = intervals[0]
        for next_start, next_end in intervals[1:]:
            if next_start < curr_end:
                curr_end = max(curr_end, next_end)
            else:
                merged.append((curr_start, curr_end))
                curr_start, curr_end = next_start, next_end
        merged.append((curr_start, curr_end))
        return merged

    # 1. Normalize inputs by merging overlapping intervals within each list
    base_merged = merge_intervals(base)
    cuts_merged = merge_intervals(cuts)

    result = []
    for b_start, b_end in base_merged:
        current_start = b_start

        # 2. For each base interval, subtract the overlapping cut intervals
        for c_start, c_end in cuts_merged:
            # If the cut is completely before the base interval, skip
            if c_end <= current_start:
                continue
            # If the cut is completely after the base interval, stop checking cuts
            if c_start >= b_end:
                break

            # If there is a gap between current_start and the start of the cut
            if c_start > current_start:
                result.append((current_start, c_start))

            # Move the current_start to the end of the cut
            current_start = max(current_start, c_end)

            if current_start >= b_end:
                break

        # 3. If there's remaining space after all relevant cuts
        if current_start < b_end:
            result.append((current_start, b_end))

    # 4. Final pass to merge adjacent intervals that touch (e.g., [0, 1) and [1, 2))
    if not result:
        return []

    result.sort()
    final_result = []
    if result:
        curr_s, curr_e = result[0]
        for i in range(1, len(result)):
            next_s, next_e = result[i]
            if next_s == curr_e:
                curr_e = next_e
            else:
                final_result.append([curr_s, curr_e])
                curr_s, curr_e = next_s, next_e
        final_result.append([curr_s, curr_e])

    return [list(i) for i in final_result]
