def to_base(n, alphabet):
    if n == 0:
        return alphabet[0]

    negative = n < 0
    n = abs(n)
    base = len(alphabet)
    res = []

    while n > 0:
        res.append(alphabet[n % base])
        n //= base

    if negative:
        res.append('-')

    return "".join(reversed(res))

def from_base(s, alphabet):
    if not s:
        raise ValueError("Empty string")

    base = len(alphabet)
    char_to_val = {char: i for i, char in enumerate(alphabet)}

    negative = False
    if s[0] == '-':
        negative = True
        s = s[1:]
        if not s:
            raise ValueError("Invalid string")

    res = 0
    for char in s:
        if char not in char_to_val:
            raise ValueError(f"Character {char} not in alphabet")
        res = res * base + char_to_val[char]

    return -res if negative else res
