function pLimit(n) {
  const queue = [];
  let activeCount = 0;

  const next = () => {
    if (queue.length === 0 || activeCount >= n) {
      return;
    }

    activeCount++;
    const { task, resolve, reject } = queue.shift();

    task().then(
      (result) => {
        resolve(result);
      },
      (error) => {
        reject(error);
      }
    ).finally(() => {
      activeCount--;
      next();
    });
  };

  return (task) => {
    return new Promise((resolve, reject) => {
      queue.push({ task, resolve, reject });
      next();
    });
  };
}

module.exports = pLimit;
