class Emitter {
  constructor() {
    this._listeners = new Map();
  }

  on(event, fn) {
    if (!this._listeners.has(event)) {
      this._listeners.set(event, []);
    }
    const handlers = this._listeners.get(event);
    const entry = { fn, once: false };
    handlers.push(entry);

    return () => this.off(event, fn);
  }

  once(event, fn) {
    if (!this._listeners.has(event)) {
      this._listeners.set(event, []);
    }
    const handlers = this._listeners.get(event);
    const entry = { fn, once: true };
    handlers.push(entry);

    return () => this.off(event, fn);
  }

  off(event, fn) {
    if (!this._listeners.has(event)) return;
    const handlers = this._listeners.get(event);
    const index = handlers.findIndex(h => h.fn === fn);
    if (index !== -1) {
      handlers.splice(index, 1);
    }
  }

  emit(event, ...args) {
    const handlers = this._listeners.get(event);
    if (!handlers || handlers.length === 0) return 0;

    // Create a snapshot of the current listeners to ensure 
    // listeners added/removed during this loop are handled correctly.
    const snapshot = [];
    for (let i = 0; i < handlers.length; i++) {
      snapshot.push(handlers[i]);
    }

    let invokedCount = 0;
    let firstError = null;

    for (const entry of snapshot) {
      // Check if the listener was removed from the original array during this emit
      if (!handlers.includes(entry)) continue;

      // If it's a 'once' listener, remove it from the source BEFORE running
      if (entry.once) {
        this.off(event, entry.fn);
      }

      try {
        entry.fn(...args);
        invokedCount++;
      } catch (err) {
        if (!firstError) firstError = err;
      }
    }

    if (firstError) {
      throw firstError;
    }

    return invokedCount;
  }
}

