const sqlTag = (strings, ...values) => {
  let text = '';
  let valuesList = [];
  let placeholderCounter = 1;

  const getPlaceholders = (val) => {
    if (val && typeof val === 'object' && 'text' in val && 'values' in val) {
      // Nested sqlTag result: Inline it
