        const idx = parseInt(num, 10) + valuesList.length;
        return `$${idx}`;
      });
      return { text: subText, values: val.values };
    }

    if (Array.isArray(val)) {
      // Array: Parenthesized comma-separated list
      const subResults = val.map(v => getPlaceholders(v));
      const subText = `(${subResults.map(r => r.text).join(', ')})`;
      const subValues = subResults.flatMap(r => r.values);
      return { text: subText, values: subValues };
    }

    // Primitive value: Create placeholder
    const placeholder = `$${placeholderCounter++}`;
    return { text: placeholder, values: [val] };
  };

  for (let i = 0; i < strings.length; i++) {
    text += strings[i];
    if (i < values.length) {
      const result = getPlaceholders(values[i]);
      text += result.text;
      valuesList.push(...result.values);
    }
  }

  return { text, values: valuesList };
};

