async function toposortTasks(tasks) {
  const results = new Map();
  const promises = new Map();
  const visiting = new Set();
  const visited = new Set();

  async function resolveTask(name) {
    if (promises.has(name)) {
      return promises.get(name);
    }

    if (visiting.has(name)) {
      throw new Error(`Dependency cycle detected involving task: ${name}`);
    }

    const task = tasks[name];
    if (!task) {
      throw new Error(`Unknown dependency: ${name}`);
    }

    const promise = (async () => {
      visiting.add(name);

      const depPromises = task.deps.map(depName => resolveTask(depName));
      const depValuesArray = await Promise.all(depPromises);

      const depValuesMap = {};
      task.deps.forEach((depName, index) => {
        depValuesMap[depName] = depValuesArray[index];
      });

      const result = await task.run(depValuesMap);

      visiting.delete(name);
      visited.add(name);
      return result;
    })();

    promises.set(name, promise);
    return promise;
  }

  try {
    const taskNames = Object.keys(tasks);
    const allResults = await Promise.all(taskNames.map(name => resolveTask(name));

    for (const name of taskNames) {
      results.set(name, await promises.get(name));
    }
    return results;
  } catch (error) {
    throw error;
  }
}

module.exports = toposortTasks;
