export class Bus<E extends Record<string, unknown>> {
  private listeners: { [K in keyof E]?: Array<(payload: E[K]) => void> } = {};

  on<K extends keyof E>(k: K, fn: (payload: E[K]) => void): () => void {
    if (!this.listeners[k]) {
      this.listeners[k] = [];
    }
    this.listeners[k]!.push(fn);
    return () => {
      this.listeners[k] = this.listeners[k]!.filter((l) => l !== fn);
    };
  }

  emit<K extends keyof E>(k: K, ...args: E[K] extends void ? [] : [E[K]]): void {
    const payload = args[0];
    const handlers = this.listeners[k];
    if (handlers) {
      for (const handler of handlers) {
        handler(payload as E[K]);
      }
    }
  }
}
